B.ac_=s(["#%@","#%@","\u7b2c %@"],t.s)
B.aBv=s(["No driver to recommend right now.","No hay conductor para recomendar.","\u6682\u65f6\u6ca1\u6709\u53ef\u63a8\u8350\u7684\u53f8\u673a\u3002"],t.s)
B.ajN=s(["Using recommendation #%@: %@","Usando recomendaci\xf3n #%@: %@","\u5df2\u91c7\u7528\u63a8\u8350\u7b2c %@ \u540d\uff1a%@"],t.s)
